.sl-team-showcase {
    position: relative;
    padding-block: clamp(3rem, 6vw, 5rem);
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-team-showcase .sl-mb-16 { margin-bottom: 4rem; }
.sl-team-showcase .text-center { text-align: center; }

.sl-team-showcase .sl-section-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 3vw, 2.25rem);
    font-weight: 700;
    margin-bottom: 1rem;
    color: var(--smartlearn-text);
}

.sl-team-showcase .sl-section-subtitle {
    font-size: 1.125rem;
    color: var(--smartlearn-text-muted);
    max-width: 600px;
    margin: 0 auto;
}

.sl-team-showcase .sl-showcase-container {
    max-width: 1000px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 2rem;
}

@media (min-width: 992px) {
    .sl-team-showcase .sl-showcase-container {
        flex-direction: row;
        align-items: stretch;
    }
}

/* Tabs Navigation */
.sl-team-showcase .sl-showcase-nav {
    display: flex;
    gap: 1rem;
    overflow-x: auto;
    padding-bottom: 1rem;
}

@media (min-width: 992px) {
    .sl-team-showcase .sl-showcase-nav {
        flex-direction: column;
        flex: 0 0 250px;
        overflow-x: visible;
        padding-bottom: 0;
    }
}

.sl-team-showcase .sl-showcase-tab {
    display: flex;
    align-items: center;
    gap: 1rem;
    background: transparent;
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.1));
    border-radius: var(--smartlearn-radius, 0.75rem);
    padding: 0.75rem;
    cursor: pointer;
    text-align: start;
    transition: background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
    min-width: 200px;
}

@media (min-width: 992px) {
    .sl-team-showcase .sl-showcase-tab {
        min-width: 0;
        border-color: transparent;
    }
}

.sl-team-showcase .sl-showcase-tab:hover {
    background-color: color-mix(in srgb, var(--smartlearn-text) 8%, transparent);
}

.sl-team-showcase .sl-showcase-tab:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

.sl-team-showcase .sl-showcase-tab[aria-selected="true"] {
    background-color: var(--smartlearn-card-bg);
    border-color: var(--smartlearn-primary);
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}

.sl-team-showcase .sl-tab-thumb {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    object-fit: cover;
    object-position: center top;
    border: 2px solid transparent;
    transition: border-color 0.2s ease;
    flex-shrink: 0;
}

.sl-team-showcase .sl-showcase-tab[aria-selected="true"] .sl-tab-thumb {
    border-color: var(--smartlearn-primary);
}

.sl-team-showcase .sl-tab-name {
    font-size: 1rem;
    font-weight: 600;
    color: var(--smartlearn-text);
}

/* Panels */
.sl-team-showcase .sl-showcase-panels {
    flex: 1;
    position: relative;
    border-radius: var(--smartlearn-radius, 1.5rem);
    overflow: hidden;
    background-color: var(--smartlearn-card-bg);
    min-height: 500px;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
}

.sl-team-showcase .sl-showcase-panel {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.4s ease;
}

.sl-team-showcase .sl-showcase-panel[hidden] {
    display: none;
}

.sl-team-showcase .sl-showcase-panel.active {
    opacity: 1;
    pointer-events: auto;
    position: relative;
}

.sl-team-showcase .sl-showcase-panel:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: -2px;
}

.sl-team-showcase .sl-panel-bg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
}

.sl-team-showcase .sl-panel-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;
}

.sl-team-showcase .sl-panel-overlay {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.28) 55%, transparent 100%);
}

.sl-team-showcase .sl-panel-content {
    position: relative;
    z-index: 1;
    padding: 3rem;
    color: #ffffff;
    transform: translateY(20px);
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.sl-team-showcase .sl-showcase-panel.active .sl-panel-content {
    transform: translateY(0);
}

.sl-team-showcase .sl-panel-tag {
    display: inline-block;
    font-size: 0.8125rem;
    font-weight: 700;
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
    padding: 0.25rem 0.75rem;
    border-radius: 9999px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.75rem;
}

.sl-team-showcase .sl-panel-name {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 3.5vw, 2.5rem);
    font-weight: 800;
    margin-bottom: 1rem;
    color: #ffffff;
}

.sl-team-showcase .sl-panel-bio {
    font-size: 1.125rem;
    line-height: 1.6;
    margin-bottom: 2rem;
    color: rgba(255, 255, 255, 0.92);
    max-width: 500px;
}

.sl-team-showcase .sl-btn {
    display: inline-block;
    padding: 0.875rem 2rem;
    border-radius: var(--smartlearn-radius, 0.5rem);
    font-weight: 600;
    font-size: 1rem;
    text-decoration: none;
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.sl-team-showcase .sl-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

.sl-team-showcase .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    border: 1px solid var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
}

.sl-team-showcase .sl-btn-primary:hover {
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
}

@media (max-width: 767px) {
    .sl-team-showcase .sl-showcase-panels {
        min-height: 600px;
    }
    .sl-team-showcase .sl-panel-content {
        padding: 2rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    .sl-team-showcase .sl-showcase-tab,
    .sl-team-showcase .sl-tab-thumb,
    .sl-team-showcase .sl-showcase-panel,
    .sl-team-showcase .sl-panel-content,
    .sl-team-showcase .sl-btn {
        transition: none;
    }
    .sl-team-showcase .sl-panel-content {
        transform: translateY(0);
    }
}

