(function() {
    var instanceCounter = 0;

    function initShowcase(root) {
        if (!root || root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        instanceCounter += 1;
        var prefix = 'sl-ts-' + instanceCounter + '-';
        var tabs = Array.prototype.slice.call(root.querySelectorAll('[role="tab"]'));
        var panels = Array.prototype.slice.call(root.querySelectorAll('[role="tabpanel"]'));
        if (!tabs.length || !panels.length) return;

        var rafId = 0;

        tabs.forEach(function(tab, idx) {
            var panel = panels[idx];
            var tabId = prefix + 'tab-' + idx;
            var panelId = prefix + 'panel-' + idx;
            tab.id = tabId;
            if (panel) {
                panel.id = panelId;
                tab.setAttribute('aria-controls', panelId);
                panel.setAttribute('aria-labelledby', tabId);
            }
        });

        function activate(targetIndex) {
            if (rafId) {
                cancelAnimationFrame(rafId);
                rafId = 0;
            }
            tabs.forEach(function(t, idx) {
                var isSelected = idx === targetIndex;
                t.setAttribute('aria-selected', isSelected ? 'true' : 'false');
                t.setAttribute('tabindex', isSelected ? '0' : '-1');
            });
            panels.forEach(function(p, idx) {
                if (idx !== targetIndex) {
                    p.classList.remove('active');
                    p.setAttribute('hidden', '');
                }
            });
            var activePanel = panels[targetIndex];
            if (activePanel) {
                activePanel.removeAttribute('hidden');
                rafId = requestAnimationFrame(function() {
                    activePanel.classList.add('active');
                    rafId = 0;
                });
            }
        }

        tabs.forEach(function(tab, index) {
            tab.addEventListener('click', function() {
                activate(index);
            });

            tab.addEventListener('keydown', function(e) {
                var isRtl = getComputedStyle(root).direction === 'rtl';
                var nextIdx = null;
                if (e.key === 'ArrowRight') {
                    nextIdx = isRtl ? (index - 1 + tabs.length) % tabs.length : (index + 1) % tabs.length;
                } else if (e.key === 'ArrowLeft') {
                    nextIdx = isRtl ? (index + 1) % tabs.length : (index - 1 + tabs.length) % tabs.length;
                } else if (e.key === 'ArrowDown') {
                    nextIdx = (index + 1) % tabs.length;
                } else if (e.key === 'ArrowUp') {
                    nextIdx = (index - 1 + tabs.length) % tabs.length;
                } else if (e.key === 'Home') {
                    nextIdx = 0;
                } else if (e.key === 'End') {
                    nextIdx = tabs.length - 1;
                }

                if (nextIdx !== null) {
                    e.preventDefault();
                    tabs[nextIdx].focus();
                    activate(nextIdx);
                }
            });
        });
    }

    function initAll() {
        document.querySelectorAll('.sl-team-showcase').forEach(initShowcase);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
